// Рилс #1: оживляем УТВЕРЖДЁННЫЕ кадры в Veo 3.1 Fast image-to-video → клипы в Телеграм → склейка в CapCut.
// Кадр не перегенерим — Veo стартует ровно с него, внешность Рыжа берётся с картинки.
// Цена: $0.15/сек со звуком → 4с ≈ $0.6, 6с ≈ $0.9; все 5 клипов (24с) ≈ $3.6. Воркфлоу временный.

// Стиль и запреты — чтобы Veo не «перерисовал» Рыжа в 3D/Pixar по ходу движения.
const STYLE = "Keep the exact 2D flat vector cartoon style of the image for the whole clip: thick clean black outlines, soft cel shading, flat colors. NOT 3D, NOT Pixar, no realistic fur. The fox must stay identical to the first frame: same face, colors, headband, wristbands, black shorts, bare cream paws.";
const NEGATIVE = "hernia, bulge or lump on the belly, deformed belly, object merging into the body, sweat drop on the ear, 3D render, Pixar style, realistic fur, photorealism, shoes, sneakers, black paws, dark gloves, subtitles, captions, on-screen text, letters, watermark, logo, extra limbs, extra fingers, distorted face, changing outfit, human characters, background music";
const VOICE = "Young energetic male voice, playful and cheeky, like a pet complaining to its owner, clear Russian pronunciation, natural pace, accurate lip-sync.";

// on: false — клип пропустить (не платить повторно за то, что устроило).
// Порядок = порядок в ролике. Сцены 3–4 (демо приложения) — видео с телефона, их тут нет.
// Текст-плашки НЕ генерим (кириллицу Veo рисует криво) — добавляются в CapCut.
const CLIPS = [
  {
    key: '1_hook',
    on: true,
    frame: "https://v3b.fal.media/files/b/0aab9714/Iuz6RGfrSebBNf0CNpqVj_GqMfseGK.png",
    duration: 6,
    camera: "Static medium shot, quick small push-in at the start to grab attention.",
    // v2: в v1 Veo «скормил» бутерброд животу. Прописываем явно: ест РТОМ, живота не касается.
    action: [
      "0-2s: Ryzh brings the sandwich up to his MOUTH and takes a big bite with his teeth, chewing with puffed cheeks. The sandwich goes into his mouth only and never touches his belly.",
      "2-3s: Still chewing, he glances down at his round belly and freezes in shock, eyes wide.",
      "3-6s: He lifts his head to the viewer and speaks, outraged, holding the bitten sandwich near his chest, his other paw on his belly.",
    ],
    line: "Стоп. Жрёшь по ночам ТЫ — а пузо растёт у МЕНЯ?!",
    sfx: "Quiet fridge hum. No music.",
  },
  {
    key: '2_intro',
    on: true,
    frame: "https://v3b.fal.media/files/b/0aab9956/j03TEZJ_NWQ3g1ujIDhTg_mhuoPvAs.png",
    duration: 6,
    camera: "Static medium shot, slight push-in as he lands.",
    action: [
      "0-2s: Ryzh finishes leaping out of the glowing phone screen and lands on the desk in front of the phone.",
      "2-6s: He waves at the viewer with a big friendly grin and speaks, then points back at the phone with his thumb.",
    ],
    // v2: в v1 «в Телеграме» прозвучало как «Телеграмбане» — ставим ударение и просим
    // произнести слово чётко (подсказка в pron → уходит в промт).
    line: "Я Рыж. Живу у тебя в Телегра́ме — и становлюсь таким, как ты.",
    pron: 'Pronounce the word «Телегра́ме» clearly and separately as "te-le-GRA-me", exactly this word, no extra syllables.',
    sfx: "A playful digital 'pop' when he jumps out of the screen, a soft thud on landing. No music.",
  },
  {
    // «До»: без реплики — кряхтит в приседе. В CapCut жёсткий стык со вспышкой на «после».
    key: '5a_result_before',
    on: true,
    frame: "https://v3b.fal.media/files/b/0aab9956/oQF_6cpK9oxtBpyKu24U-_o2Wj8zzb.png",
    duration: 4,
    camera: "Static medium shot.",
    // v2: в v1 капля пота прилипла к уху, а на животе вылезла «грыжа». Приседания и пот
    // оставляем (естественно), но фиксируем: капля на лбу, живот гладкий.
    // Без звука (дешевле, $0.10/с) — пыхтение наложить в CapCut; нужно в клипе — audio: true.
    action: [
      "0-4s: Ryzh does two natural bodyweight squats, straining, determined face, puffing. A single small sweat drop sits on his forehead just below the headband and slowly slides down his forehead. His round belly stays smooth and soft with a small simple belly button, no bulges or lumps.",
    ],
    line: "",
    audio: false,
    sfx: "",
  },
  {
    key: '5b_result_after',
    on: false, // ок с первого прогона
    frame: "https://v3b.fal.media/files/b/0aab9956/KuCcZyboKHJlcUbU7Y0Kc_tEXEOlDj.png",
    duration: 4,
    camera: "Static medium shot, slight slow push-in.",
    action: [
      "0-4s: Ryzh flexes his bicep, kisses it, grins at the viewer and speaks proudly.",
    ],
    line: "Держишь норму — и пузо уходит. У обоих!",
    sfx: "A bright 'ding' sparkle sound on the flex. No music.",
  },
  {
    key: '6_cta',
    on: false, // ок с первого прогона
    frame: "https://v3b.fal.media/files/b/0aab977f/g728kX2AST-SjW-X-Z8JB_iCs7LNBf.png",
    duration: 4,
    camera: "Static medium shot, slight slow push-in toward his face.",
    action: [
      "0-1s: Ryzh holds the raised finger, winking, as if he has an idea.",
      "1-4s: He lowers the finger to point straight at the camera and speaks with a cheeky pleading grin.",
    ],
    line: "Заведи своего лиса. Не бросай меня, а?",
    sfx: "Light cheerful 'ding' at the end. No music.",
  },
];

const out = [];
for (const s of CLIPS) {
  if (!s.on) continue;
  const d = Math.round(Number(s.duration) || 8);
  const prompt = [
    'Animate this image. ' + STYLE,
    'Camera: ' + s.camera,
    'Action: ' + s.action.join(' '),
    s.line ? 'Dialogue: the fox says in Russian: "' + s.line + '"' : '',
    s.pron || '',
    s.line ? 'Voice: ' + VOICE : 'The fox does not speak any words.',
    s.audio === false ? '' : 'Audio: ' + (s.sfx || 'No music.'),
    'Absolutely no subtitles, no captions, no on-screen text or letters anywhere in the frame.',
  ].filter(Boolean).join('\n');
  out.push({ json: {
    key: s.key,
    line: s.line || '',
    image_url: s.frame,
    prompt,
    negative_prompt: NEGATIVE,
    duration: d <= 4 ? '4s' : d <= 6 ? '6s' : '8s',
    audio: s.audio !== false,
  } });
}
return out;
